using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;
namespace Gunt.ControlCenter.Views {
 public sealed partial class MainWindow {
  void BuildDevelopmentSessions(){Text("실행 순서와 대상 폴더를 미리 확인합니다. 실행 완료는 각 프로그램의 시작 요청 기준입니다.",true);try{var p=vm.Service.ActiveProject();Text("현재 프로젝트: "+p.Name+" · "+p.Directory,true);}catch(Exception e){Text(e.Message,true);}var a=Actions();PageButton(a,"프로젝트 선택","developer-setup");sessionList=DataList("개발 세션 목록",160);sessionList.ItemsSource=vm.Service.Sessions().Presets;content.Children.Add(sessionList);sessionDetails=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=Muted,Margin=new Thickness(0,0,0,12)};content.Children.Add(sessionDetails);sessionList.SelectionChanged+=delegate{try{var p=sessionList.SelectedItem as DevelopmentSession;sessionDetails.Text=p==null?"세션을 선택하세요.":vm.Service.SessionPreview(vm.Service.ActiveProject(),p);}catch(Exception e){sessionDetails.Text=e.Message;}};if(sessionList.Items.Count>0)sessionList.SelectedIndex=0;a=Actions();Action(a,"개발 세션 시작",()=>LaunchSessionFromUi(false));Action(a,"이전 개발 세션 다시 시작",()=>LaunchSessionFromUi(true));Action(a,"개발 세션 종료 기록",()=>vm.Service.EndDevelopmentSession());a=Actions();Action(a,"새 세션",()=>{Dispatcher.Invoke((Action)(()=>EditDevelopmentSession(new DevelopmentSession{Id="user-"+Guid.NewGuid().ToString("N"),Name="새 개발 세션"})));return "세션 편집을 마쳤습니다.";});Action(a,"선택 세션 편집",()=>{var selected=SelectedSession();Dispatcher.Invoke((Action)(()=>EditDevelopmentSession(vm.Service.Json.Deserialize<DevelopmentSession>(vm.Service.Json.Serialize(selected)))));return "세션 편집을 마쳤습니다.";});Action(a,"세션 복제",()=>{var copy=vm.Service.Json.Deserialize<DevelopmentSession>(vm.Service.Json.Serialize(SelectedSession()));copy.Id="user-"+Guid.NewGuid().ToString("N");copy.Name+=" 복사";copy.Builtin=false;vm.Service.SaveSession(copy);Dispatcher.Invoke((Action)(()=>Show("development-sessions")));return "세션을 복제했습니다.";});Action(a,"사용자 세션 삭제",()=>{var selected=SelectedSession();if(selected.Builtin)throw new ArgumentException("기본 세션은 삭제하지 않습니다.");bool yes=Dispatcher.Invoke(new Func<bool>(()=>Decide("개발 세션 삭제",selected.Name+"을 삭제할까요? 프로그램과 프로젝트 폴더는 유지합니다.","삭제","취소")==0));if(yes){vm.Service.DeleteSession(selected.Id);Dispatcher.Invoke((Action)(()=>Show("development-sessions")));}return yes?"사용자 세션을 삭제했습니다.":"삭제를 취소했습니다.";});var history=new TextBox{Text=String.Join("\n",vm.Service.SessionHistory().Take(10).Select(x=>x.Started+" · "+x.PresetId+" · "+x.Result+" · "+String.Join(", ",x.Actions.Select(item=>DeveloperText.Action(item.Action)+":"+item.Status))+(x.Active?" · 종료 기록 전":""))),IsReadOnly=true,Height=110,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};AutomationProperties.SetName(history,"개발 세션 실행 이력");content.Children.Add(history);}
  DevelopmentSession SelectedSession(){return Dispatcher.Invoke(new Func<DevelopmentSession>(()=>{var s=sessionList.SelectedItem as DevelopmentSession;if(s==null)throw new ArgumentException("세션을 선택하세요.");return s;}));}
  string LaunchSessionFromUi(bool resume){ProjectEntry p;DevelopmentSession s;DeveloperPreferences prefs=null;if(resume){var last=vm.Service.ResumeConfiguration();p=last.Item1;s=last.Item2;prefs=last.Item3;}else{p=vm.Service.ActiveProject();s=SelectedSession();}string summary=vm.Service.SessionPreview(p,s,prefs);bool yes=Dispatcher.Invoke(new Func<bool>(()=>Decide("개발 세션 실행",summary,"이 구성으로 시작","취소")==0));if(!yes)return "개발 세션 시작을 취소했습니다.";bool custom=s.Actions.Any(a=>a.Enabled&&a.Kind=="command");bool consent=!custom||Dispatcher.Invoke(new Func<bool>(()=>Decide("프로젝트 명령 실행 동의",p.Name+"\n"+String.Join("\n",p.Commands??new List<string>()),"이 명령 실행 허용","명령 제외")==0));var result=vm.Service.StartSession(p,s,custom&&consent,false,prefs);string report=String.Join("\n",result.Actions.Select(x=>x.ToString()));Dispatcher.Invoke((Action)(()=>{if(sessionDetails!=null)sessionDetails.Text=report;}));return result.Result+" · "+report;}
  void EditDevelopmentSession(DevelopmentSession session){StackPanel panel;var w=EditorWindow("개발 세션 편집",out panel);var name=EditBox(panel,"세션 이름",session.Name);var mode=Choice(panel,"실행 방식",new[]{new ChoiceOption("sequential","순차 요청"),new ChoiceOption("independent","독립 요청")},session.Mode);var terminal=Choice(panel,"세션 터미널",new[]{new ChoiceOption("","프로젝트 설정 상속"),new ChoiceOption("windows-terminal","Windows Terminal"),new ChoiceOption("cmd","CMD")},session.TerminalHost??"");var profile=Choice(panel,"세션 작업공간",new[]{new ChoiceOption("","프로젝트 설정 상속")}.Concat(vm.Service.Profiles().Select(p=>new ChoiceOption(p.Id,p.Name))),session.WorkspaceProfile??"");var allow=new CheckBox{Content="프로젝트 명령이 없을 때 이 세션의 자동 실행 허용",Foreground=TextColor,IsChecked=session.AllowAutomation};panel.Children.Add(allow);var list=DataList("세션 동작 순서",140);list.ItemsSource=session.Actions.ToArray();panel.Children.Add(list);var kinds=Choice(panel,"추가할 동작",new[]{"ai","project-terminal","ide","codex","opencode","wsl","cmd","powershell","terminal","folder","repository","command"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),"ide");foreach(var t in vm.Service.Developer().Tools){var add=new Button{Content="도구 추가: "+t.Name};var tool=t;add.Click+=delegate{session.Actions.Add(new SessionAction{Kind="tool",Value=tool.Id});list.ItemsSource=session.Actions.ToArray();};panel.Children.Add(add);}var buttons=new WrapPanel();panel.Children.Add(buttons);var addButton=new Button{Content="동작 추가"};addButton.Click+=delegate{session.Actions.Add(new SessionAction{Kind=Convert.ToString(kinds.SelectedValue)});list.ItemsSource=session.Actions.ToArray();};buttons.Children.Add(addButton);foreach(string action in new[]{"사용 전환","위로","아래로","동작 제거"}){string operation=action;var b=new Button{Content=action};b.Click+=delegate{var selected=list.SelectedItem as SessionAction;if(selected==null)return;int index=session.Actions.IndexOf(selected);if(operation=="사용 전환")selected.Enabled=!selected.Enabled;else if(operation=="동작 제거")session.Actions.Remove(selected);else{int next=index+(operation=="위로"?-1:1);if(next>=0&&next<session.Actions.Count){session.Actions.RemoveAt(index);session.Actions.Insert(next,selected);}}list.ItemsSource=session.Actions.ToArray();list.SelectedItem=selected;};buttons.Children.Add(b);}SaveEditor(w,panel,()=>{session.Name=name.Text.Trim();session.Mode=Convert.ToString(mode.SelectedValue);session.TerminalHost=Convert.ToString(terminal.SelectedValue);session.WorkspaceProfile=Convert.ToString(profile.SelectedValue);session.AllowAutomation=allow.IsChecked==true;vm.Service.SaveSession(session);});w.ShowDialog();Show("development-sessions");}
  void BuildSmartAutomation(){Text("규칙은 처음에 모두 중지 상태입니다. 기존 상단 바가 전원·화면·설정한 앱의 변화만 10초 간격으로 확인합니다. 세션 종료는 수동 종료 기록 기준이며 프로그램을 종료하지 않습니다.",true);ruleList=DataList("스마트 자동화 규칙",170);ruleList.ItemsSource=vm.Service.Automation().Rules;content.Children.Add(ruleList);var details=new TextBlock{Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,12)};content.Children.Add(details);ruleList.SelectionChanged+=delegate{var selected=ruleList.SelectedItem as AutomationRule;if(selected!=null)details.Text=DeveloperText.Trigger(selected.Trigger)+" → "+DeveloperText.Action(selected.Action)+" · 우선순위 "+selected.Priority+" · 재실행 대기 "+selected.CooldownSeconds+"초\n최근 실행: "+DesktopService.S(vm.Service.State("automation-times"),selected.Id,"없음");};var a=Actions();Action(a,"규칙 추가",()=>{Dispatcher.Invoke((Action)(()=>EditAutomationRule(new AutomationRule{Name="새 규칙"})));return "자동화 규칙 편집을 마쳤습니다.";});Action(a,"규칙 편집",()=>{var rule=SelectedRule();var copy=vm.Service.Json.Deserialize<AutomationRule>(vm.Service.Json.Serialize(rule));Dispatcher.Invoke((Action)(()=>EditAutomationRule(copy)));return "규칙 편집을 마쳤습니다.";});Action(a,"사용 / 중지",()=>{var rule=SelectedRule();if(!rule.Enabled&&!Dispatcher.Invoke(new Func<bool>(()=>Decide("자동화 사용",rule.Name+"\n조건: "+DeveloperText.Trigger(rule.Trigger)+"\n동작: "+DeveloperText.Action(rule.Action)+"\n조건이 맞으면 사용자 조작 없이 실행됩니다.","이 규칙 사용","취소")==0)))return "규칙 사용을 취소했습니다.";rule.Enabled=!rule.Enabled;vm.Service.SaveRule(rule);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));return rule.Enabled?"규칙 사용을 켰습니다.":"규칙을 중지했습니다.";});Action(a,"규칙 삭제",()=>{var rule=SelectedRule();if(Dispatcher.Invoke(new Func<bool>(()=>Decide("규칙 삭제",rule.Name+"을 삭제할까요?","삭제","취소")==0))){vm.Service.DeleteRule(rule.Id);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));}return "규칙 삭제 처리를 마쳤습니다.";});var events=new TextBox{Text=vm.Service.AutomationHistory(),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=180,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};content.Children.Add(events);Action(a,"실행 이력 갱신",()=>{string text=vm.Service.AutomationHistory();Dispatcher.Invoke((Action)(()=>events.Text=text));return "규칙 이력을 갱신했습니다.";});}
  AutomationRule SelectedRule(){return Dispatcher.Invoke(new Func<AutomationRule>(()=>{var rule=ruleList.SelectedItem as AutomationRule;if(rule==null)throw new ArgumentException("규칙을 선택하세요.");return rule;}));}
  void EditAutomationRule(AutomationRule rule){StackPanel panel;var w=EditorWindow("스마트 자동화 규칙 편집",out panel);var name=EditBox(panel,"규칙 이름",rule.Name);var trigger=Choice(panel,"조건",new[]{"session-started","session-ended","application-running","ac-connected","battery","monitor-changed"}.Select(x=>new ChoiceOption(x,DeveloperText.Trigger(x))),rule.Trigger);var triggerValue=EditBox(panel,"조건 값 (앱 이름 또는 프로젝트 ID, 세션은 비우면 모두)",rule.TriggerValue);var action=Choice(panel,"실행 동작",new[]{"profile","restore-owned","monitor-show","monitor-hide","wallpaper-pause","wallpaper-play","open-project","session"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),rule.Action);var value=EditBox(panel,"동작 대상 ID (프로필·프로젝트·세션)",rule.Value);panel.Children.Add(new TextBlock{Text="프로필: "+String.Join(", ",vm.Service.Profiles().Select(x=>x.Id))+"\n프로젝트: "+String.Join(", ",vm.Service.Projects().Select(x=>x.Id))+"\n세션: "+String.Join(", ",vm.Service.Sessions().Presets.Select(x=>x.Id)),Foreground=Muted,TextWrapping=TextWrapping.Wrap});var power=Choice(panel,"추가 전원 조건",new[]{new ChoiceOption("any","제한 없음"),new ChoiceOption("ac","AC 연결"),new ChoiceOption("battery","배터리")},rule.Power);var exceptions=EditBox(panel,"제외할 실행 앱 이름 (쉼표 구분)",String.Join(",",rule.Exceptions));var priority=EditBox(panel,"우선순위 0–100",rule.Priority.ToString());var cooldown=EditBox(panel,"재실행 대기 10–86400초",rule.CooldownSeconds.ToString());panel.Children.Add(new TextBlock{Text="저장만으로 새 규칙을 켜지 않습니다. 목록의 사용/중지에서 명시적으로 켜세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap});SaveEditor(w,panel,()=>{rule.Name=name.Text.Trim();rule.Trigger=Convert.ToString(trigger.SelectedValue);rule.TriggerValue=triggerValue.Text.Trim();rule.Action=Convert.ToString(action.SelectedValue);rule.Value=value.Text.Trim();rule.Power=Convert.ToString(power.SelectedValue);rule.Exceptions=exceptions.Text.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToList();rule.Priority=Int32.Parse(priority.Text);rule.CooldownSeconds=Int32.Parse(cooldown.Text);vm.Service.SaveRule(rule);});w.ShowDialog();Show("smart-automation");}
 }
}
